-- 0288 misterioso_pdf (inventario_misterioso_pdf) — borra placeholder + entidades + puntuaciones reales
DELETE FROM puntuaciones WHERE categoria='misterioso';
DELETE FROM entidades WHERE fuente='inventario_misterioso_pdf';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','misterio','Lugares de misterio y leyendas','Conocida como la "puerta de los magos". Famosa por sus procesiones de brujas en la Edad Media y por el linaje de los "Blanes". El convento de San Francisco tiene leyendas de apariciones de monjas y fenómenos paranormales. Atractivos: Castillo de Morella, Convento de San Francisco, murallas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','misterio','Lugares de misterio y leyendas','El misterio de la calle Dalt. Leyendas de la Inquisición, callejones oscuros con apariciones de antiguos reos, y las historias de brujería en la huerta valenciana (como la "bruixa" de Patraix). Atractivos: Barrio del Carmen, Tribunal de las Aguas, Cauce del río Turia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','misterio','Lugares de misterio y leyendas','El Cementerio de Montjuïc es un epicentro de paranormal y espiritismo. En el Barrio Gótico se reportan apariciones en el antiguo barrio judío y en el Palau Reial Major. Leyendas de la "Casa de l''Ardiaca". Atractivos: Cementerio de Montjuïc, Barrio Gótico, Hospital de la Santa Creu.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50265','misterio','Lugares de misterio y leyendas','Único pueblo de España oficialmente excomulgado por la Iglesia (hasta 1998). Cuna de la brujería aragonesa. El castillo, en ruinas, es visitable y centro de rituales paganos y avistamientos de luces inexplicables. Escenario de la leyenda de la Campana de Velilla. Atractivos: Castillo de Trasmoz, Cerro de la Mora.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','misterio','Lugares de misterio y leyendas','Turismo oscuro y parapsicología. Escenario de una de las batallas más crueles de la Guerra Civil. Visitable mediante tours guiados. Fenómenos de psicofonía, voces, pasos y apariciones de soldados caídos. Atractivos: Pueblo Viejo de Belchite (en ruinas).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31264','misterio','Lugares de misterio y leyendas','Capital española de la brujería. Origen del famoso auto de fe de Logroño (1610). Las cuevas son completamente visitables y se celebran akelarres modernos. Fuerte energía telúrica y turismo esotérico masivo. Atractivos: Cueva de las Brujas (Akelarre), Museo de las Brujas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','misterio','Lugares de misterio y leyendas','Aparición de la Virgen a un pastor en un espino (leyenda fundacional). Conexión con antiguos cultos paganos vascos (Sorginak) y la mitología de basajaun y lamias en las cuevas de la zona. Atractivos: Santuario de Arantzazu, Cuevas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','misterio','Lugares de misterio y leyendas','Mayor enclave templario de la Península. Leyendas sobre el tesoro templario más grande de la Cristiandad escondido en sus muros, símbolos esotéricos y un supuesto pasadizo que lo conecta con el castillo de Cornatel【turn2search15】【turn2search16】【turn2search19】. Atractivos: Castillo de los Templarios (siglo XII), casco histórico, Museo del Bierzo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42164','misterio','Lugares de misterio y leyendas','Soria es la cuna de las leyendas de Gustavo Adolfo Bécquer ("Los ojos verdes", "El rayo de luna"). La zona de la Sierra de Urbión está plagada de leyendas de las "xanas", súcubos y aparecidos en las lagunas glaciares. Atractivos: Casa Fuerte de San Leonardo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','misterio','Lugares de misterio y leyendas','La Cueva de Salamanca es el lugar donde según la leyenda el diablo enseñaba magia negra a 7 alumnos (quedando uno como pago). Punto de peregrinación esotérica y turismo de brujería y nigromancia. Atractivos: Cueva de Salamanca, Universidad, Casa de las Conchas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','misterio','Lugares de misterio y leyendas','Centro místico de España. Misticismo extremo, levitaciones (Santa Teresa de Jesús), y apariciones en el casco antiguo amurallado. Conexión con la Orden del Temple. Atractivos: Murallas, Convento de Santa Teresa.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45053','misterio','Lugares de misterio y leyendas','Castillo templario con evidentes símbolos esotéricos. Leyendas de tesoros escondidos y apariciones de caballeros caídos en reconquistas. Atractivos: Castillo de Consuegra, Molinos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','misterio','Lugares de misterio y leyendas','La "Cueva de la Hiedra" es famosa por rituales de brujería. El municipio es conocido por su historia de aquíes y el conocimiento de los ciclos astrales desde tiempos celtas y romanos. Atractivos: Castillo de Peña Bermeja, Cueva de la Iedra.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','misterio','Lugares de misterio y leyendas','El Palacio de Linares es la casa encantada más famosa de España (apariciones de la hija asesinada). La Estación de Chamberí ("Estación fantasma") ofrece tours de fenómenos paranormales. El cementerio de la Almudena tiene alta actividad espiritista. Atractivos: Palacio de Linares, Estación de Chamberí, Cementerio de la Almudena, Parque del Retiro.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','misterio','Lugares de misterio y leyendas','La "Casa de la Mora" es un hotel y restaurante famoso por las apariciones de una mujer y soldados de la Guerra Civil. Muy popular entre los investigadores paranormales de Madrid. Atractivos: Casa de la Mora, Sierra de Guadarrama.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','misterio','Lugares de misterio y leyendas','La leyenda de la princesa musulmana que, traicionada por enamorarse de un noble cristiano, fue convertida en gallina por su padre brujo. Cada 23 de abril su sombra recorre las calles cacereñas próximas al palacio. El Parador acumula testimonios de presencias【turn11search7】【turn11search9】【turn15search3】. Atractivos: Parador de Cáceres (antiguos palacios góticos), casco antiguo Patrimonio UNESCO.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','misterio','Lugares de misterio y leyendas','La leyenda del hallazgo de la virgen por un pastor y la aparición de la virgen. Conexión templaria en la zona y misticismo de los caballeros ocultos en el monasterio. Atractivos: Monasterio de Guadalupe.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','misterio','Lugares de misterio y leyendas','La Casa de las Cabezas es parada obligatoria de terror histórico. El convento de Santa Clara tiene leyendas de monjas emparedadas. Actividad paranormal reportada en el Cementerio de San Fernando. Atractivos: Casa de las Cabezas, Convento de Santa Clara, Cementerio de San Fernando.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','misterio','Lugares de misterio y leyendas','El cementerio de San José (sobre un antiguo cementerio morisco) es uno de los lugares más estudiados por psicofonías. El Albaicín alberga leyendas de duendes y apariciones de la época nazarí. Atractivos: Alhambra, Barrio del Albaicín, Cementerio de San José.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','misterio','Lugares de misterio y leyendas','En 1550 se manifestaron extrañas luces y una aparición divina en la Puerta del Lobo . En una cueva aparecieron formas blancas, luces y una figura infantil misteriosa【turn17search11】【turn8search7】. Atractivos: Casco renacentista (Patrimonio UNESCO), Universidad antigua, Puerta del Lobo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','misterio','Lugares de misterio y leyendas','La Laguna es conocida como la "ciudad de los conventos y los aparecidos". La Casa Lercaro es una de las casas encantadas más activas de España (aparición de Catalina Lercaro). Rutas de misterio nocturnas muy concurridas. Atractivos: Casa Lercaro, Hospital de Nuestra Señora de los Dolores, Convento de Santa Catalina.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','misterio','Lugares de misterio y leyendas','Historias de brujería canaria y apariciones de ánimas en pena. La erupción volcánica de 1706 dejó ruinas malditas y un fuerte legado de leyendas locales. Atractivos: Convento de San Francisco, Cueva de San Marcos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','misterio','Lugares de misterio y leyendas','Famoso por la Santa Compaña y tradiciones meigas. Se pueden visitar lugares donde ocurrieron supuestos avistamientos de procesiones de difuntos. El turismo místico es parte de su identidad. Atractivos: Catedral, Museo Catedralicio, Aldea de Galdo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','misterio','Lugares de misterio y leyendas','Conocida como la "ciudad de la brujería" en Galicia. Famosa por sus cementerios antiguos y la fuerte presencia de meigas (brujas) en su historia local documentada y leyendas urbanas. Atractivos: Iglesia de Santa María A Nova, Museo de la Campana.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','misterio','Lugares de misterio y leyendas','El misterio de la Cruz de los Ángeles y las apariciones de la "Dama de Blanco" en la Universidad. Fuerte tradición de "xanas" (ninfas de los ríos) en las afueras. Atractivos: Cámara Santa, Universidad.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','misterio','Lugares de misterio y leyendas','Aunque es un pueblo histórico, sus callejas ocultan leyendas de la Inquisición y casas solariegas con sonidos y presencias (como la Casa del Águila y la Parra). Fuerte turismo esotérico en la zona rural de Cantabria. Atractivos: Colegiata, Cuevas de Altamira, Casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','misterio','Lugares de misterio y leyendas','Desde 1971, en la cocina de la casa de María Gómez Cámara empezaron a aparecer —y reaparecer tras ser picadas— manchas con forma de rostros humanos en el suelo de cemento. Es uno de los casos paranormales más famosos del mundo y la casa sigue siendo visitable en el pueblo【turn1search0】【turn1search3】. Atractivos: Casa de "Las Caras", Museo de Bélmez.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18176','misterio','Lugares de misterio y leyendas','Tras la expulsión morisca fue repoblado por familias gallegas que trajeron el culto a las meigas. Cada calle tiene su historia mágica. Símbolos esotéricos y figuras repartidas por el pueblo【turn2search12】【turn3search1】【turn12search10】【turn12search11】【turn12search12】【turn12search13】【turn12search14】【turn18search9】【turn18search10】. Atractivos: "Pueblo de las Brujas" de la Alpujarra, Museo de la Brujería, Casa de Baba Yaga, Casa de Hansel y Gretel, Fuente de los Cántaros, Cueva del Ojo de Guayota, Fuente del Dragón.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','misterio','Lugares de misterio y leyendas','Tildado de "pueblo maldito", sus calles han sido escenario de numerosas leyendas, entre ellas la del jinete sombrío que aparece cabalgando las noches de luna llena por la zona alta del pueblo【turn15search9】. Atractivos: Casco histórico, vistas del Guadiana.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','misterio','Lugares de misterio y leyendas','Existen leyendas locales de "cortijos malditos" y apariciones espectrales en las sierras circundantes, ligadas a un sustrato de brujería rural que sobrevivió hasta el siglo XX【turn15search11】. Atractivos: Gruta de las Maravillas, Sierra de Aracena.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','misterio','Lugares de misterio y leyendas','Su leyenda fundacional es en sí un misterio: un pastor desaparece misteriosamente y en el lugar donde se le vio por última vez brota un manantial que da origen al pueblo【turn15search21】. Atractivos: Plaza de los Toros, iglesia de San Jerónimo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','misterio','Lugares de misterio y leyendas','El fantasma de doña Blanca en la plaza de Orive (leyenda del noble Carlos Ucel y su hija blanca y hermosa). El fantasma de la Mezquita (alojo nocturno). Medina Azahara con leyendas de amor y poder. La Facultad de Derecho, sobre un antiguo hospital psiquiátrico, es uno de los edificios con más actividad paranormal de Andalucía【turn5search18】【turn5search22】【turn8search6】【turn17search6】【turn17search7】【turn17search8】【turn17search9】【turn17search10】【turn18search7】【turn18search8】. Atractivos: Mezquita-Catedral, Medina Azahara, Facultad de Derecho, barrio de la Judería, Plaza de Orive.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','misterio','Lugares de misterio y leyendas','El Teatro Cervantes guarda la historia de Conchita Robles, actriz asesinada en 1922 cuyas apariciones siguen reportándose. Además, en la provincia existieron dos casos de apariciones marianas y apariciones ligadas al accidente ferroviario de Fiñana en 1943【turn17search17】. Atractivos: Teatro Cervantes, Alcazaba, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','misterio','Lugares de misterio y leyendas','Según la leyenda, en sus muros falleció el conde Don Julián y está enterrado el "mayor traidor de España". Numerosos visitantes reportan la aparición del fantasma del conde y de doña Violante de Luna, sobrina del Papa Luna, cuya tumba nunca se halló【turn4search13】【turn4search16】. Atractivos: Castillo de Loarre (el románico mejor conservado de Europa).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','misterio','Lugares de misterio y leyendas','Una de las "tierras de brujas" más documentadas de la Sierra de Albarracín. La leyenda del pastor y las brujas de Jabaloyas cuenta que descendían volando sobre escobas para robar el vino de las bodegas de Frías de Albarracín【turn8search20】【turn10search9】. Atractivos: Monte Javalón, Ermita de la Virgen de Trinidad, iglesia de la Asunción.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44109','misterio','Lugares de misterio y leyendas','Escenario complementario de la leyenda de las brujas de Jabaloyas. La tradición oral mantiene viva la historia del "Tío Candelas" y su bodega vigilada【turn10search10】. Atractivos: Bodegas tradicionales, casco urbano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','misterio','Lugares de misterio y leyendas','Uno de los pueblos más mágicos de España, con leyendas de apariciones en sus callejuelas, una abundante tradición de brujería en la sierra y un caso documentado de experiencia paranormal en el casco urbano【turn10search6】【turn10search8】. Atractivos: Murallas, casco medieval, Plaza Mayor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','misterio','Lugares de misterio y leyendas','Vigía del Camino de Santiago desde el siglo IX. Sus murallas acumulan leyendas de prisioneros, nobles y reyes, y son frecuentes las rutas nocturnas de misterio【turn7search5】【turn7search7】【turn13search6】. Atractivos: Castillo de Castrojeriz, Convento de San Antón, excolegiata de Nuestra Señora del Manzano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','misterio','Lugares de misterio y leyendas','"En Calatañazor perdió Almanzor el tambor". Pueblo detenido en el tiempo donde, según la leyenda, cayó el invencible caudillo musulmán. El ambiente medieval invita a rutas de leyenda【turn7search11】【turn7search12】. Atractivos: Villa medieval amurallada, castillo, plazuelta del árbol torcido.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','misterio','Lugares de misterio y leyendas','En lo alto del cerro de La Muela aún se siente, según los visitantes, "la fuerza de un pueblo que resistió al Imperio Romano". Numancia es un lugar cargado de energía histórica y leyendas de sacrificio colectivo【turn7search2】. Atractivos: Numancia, yacimiento celtíbero.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42029','misterio','Lugares de misterio y leyendas','Considerado durante siglos un foco de brujería, aparece recogido en las crónicas de cazas de brujas de la provincia, junto con otros pueblos sorianos de tradición esotérica【turn7search14】. Atractivos: Casco urbano serrano, paisaje de la Sierra de Urbión.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','misterio','Lugares de misterio y leyendas','La leyenda del fantasma de Masegoso cuenta que el pueblo entero desapareció tras un envenenamiento por envidia. Es uno de los enigmas rurales de Soria【turn7search3】【turn14search5】. Atractivos: Ruinas del pueblo despoblado.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','misterio','Lugares de misterio y leyendas','Cuna de la leyenda del Hombre Pez de Liérganes, el ser mitad hombre mitad pez que, según la tradición del siglo XVIII, fue visto en distintas costas europeas. El pueblo tiene un marcado carácter de leyenda【turn9search8】【turn9search11】. Atractivos: Puente Romano, Centro de Interpretación del Hombre Pez, casonas nobiliarias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','misterio','Lugares de misterio y leyendas','Capital de Liébana, tierra de ojáncanos, anjanas y leyendas de tesoros ocultos. Existe la leyenda de la "Mansión de los Espíritus", una casona habitada por almas perdidas【turn11search13】【turn11search14】. Atractivos: Torre del Infantado, casco histórico, Picos de Europa.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','misterio','Lugares de misterio y leyendas','El castillo se levantó sobre una ermita del siglo IX y aún conserva una necrópolis en su patio. Existe un sainete teatral tradicional, "El fantasma del Castillo de Argüeso", basado en la traición de Don Fernando de Mier【turn14search10】【turn14search13】. Atractivos: Castillo de Argüeso, necrópolis del patio de armas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','misterio','Lugares de misterio y leyendas','La Casa de los Bayón fue escenario, a comienzos del siglo XX, de uno de los casos de poltergeist más famosos de España, documentado incluso con intervención de la Guardia Civil. Es considerada una de las casas rurales más embrujadas del país【turn16search19】【turn17search2】【turn17search3】. Atractivos: Casa del Bayón (Rayán), valle minero.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','misterio','Lugares de misterio y leyendas','En abril de 1854 todos los habitantes de Mengollo aparecieron muertos sin signos de violencia. Es la "leyenda del pueblo fantasma de Asturias", uno de los enigmas sin resolver de la región【turn14search0】【turn14search3】. Atractivos: Pueblo despoblado de Mengollo, valle del Quirós.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','misterio','Lugares de misterio y leyendas','El valle fue, según la leyenda, la prisión donde un hidalgo cumplió cadena perpetua por asesinar al cura del pueblo por orden de su señor. Es una ruta de misterio destacada【turn16search17】. Atractivos: Valle del Desterrado, cascada de Seimeira.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','misterio','Lugares de misterio y leyendas','Según la tradición, la noche de San Juan aparece un hada encantada en la cascada de la Pena do Encanto para hechizar a quien la vea. Una de las rutas mágicas más señaladas de Asturias【turn16search18】. Atractivos: Ruta de la Pena do Encanto, cascada.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','misterio','Lugares de misterio y leyendas','Crónica de brujería marinera: si los marineros se cruzaban con una mujer considerada bruja al salir a faenar, regresaban a casa por considerar perdido el día. Existen leyendas de viudas y apariciones en la noche de Difuntos【turn11search17】【turn11search19】. Atractivos: Anfiteatro marinero, puerto.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','misterio','Lugares de misterio y leyendas','En sus montes y acantilados vivían, según la tradición, las meigas. Es uno de los enclaves gallegos donde más persiste la cultura de la brujería costera【turn13search0】. Atractivos: Cabo Ortegal, acantilados más altos de Europa, calas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','misterio','Lugares de misterio y leyendas','La Cova da Serpe es escenario de una de las leyendas más famosas de Galicia: una serpiente gigante que devoraba ganado y exigía sacrificios hasta que un caballero la venció con una lanza bendita【turn11search4】【turn11search6】. Atractivos: A Cova da Serpe, torre de San Paio de Narla, mirador natural.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36014','misterio','Lugares de misterio y leyendas','Considerada una de las "ciudades donde viven las brujas de Galicia". Su pasado judío y su posición fronteriza han generado un sustrato de leyendas de apariciones y prácticas esotéricas【turn13search1】. Atractivos: Catedral fortificada, barrio judío, Camino Portugués.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','misterio','Lugares de misterio y leyendas','La Casa de la Sirena, una de las Casas Colgadas, protagoniza una de las leyendas más famosas de la ciudad. El Parador, antiguo convento de San Pablo, acumula relatos de apariciones de monjas【turn13search11】【turn13search12】【turn13search14】. Atractivos: Casas Colgadas, Casa de la Sirena, Parador de Cuenca (antiguo convento).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16135','misterio','Lugares de misterio y leyendas','Uno de los pueblos abandonados más impresionantes de España, frecuentado por amantes del misterio y la fotografía de ruinas【turn4search9】. Atractivos: Pueblo abandonado, ruinas en lo alto de un cerro a 1.100 metros.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16033','misterio','Lugares de misterio y leyendas','Múltiples apariciones: el espectro de una joven noble vestida de blanco encerrada por su familia tras un amor prohibido; el fantasma de la emperatriz Eugenia de Montijo (última propietaria del castillo en el siglo XIX); y la figura histórica de Juana la Beltraneja. Actores que han rodado en el castillo también han reportado presencias【turn2search0】【turn2search1】【turn2search2】. Atractivos: Castillo de Belmonte (siglo XV, forma de estrella de seis puntas), casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02010','misterio','Lugares de misterio y leyendas','Sus cuevas subterráneas, el barrio árabe y su conjunto histórico amurallado son escenario de leyendas y rutas de misterio que recorren sus callejas medievales【turn16search0】【turn16search1】. Atractivos: Castillo del siglo XV, cuevas del Agujero, barrio árabe.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','misterio','Lugares de misterio y leyendas','Posiblemente la ciudad con más rutas de misterio nocturnas de España. Sus calles estrechas y oscuras guardan apariciones reportadas en la Casa de las Cabezas, el Castillo de San Servando y el barrio judío. Existen tours específicos "Toledo Siniestro"【turn4search0】【turn4search1】【turn3search5】. Atractivos: Casa de las Cabezas, criptas y momias, Castillo de San Servando, casco antiguo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17220','misterio','Lugares de misterio y leyendas','Cuna de las célebres "Brujas de Viladrau", perseguidas en el juicio de brujería de 1618-1622. La ermita de Sant Segimon era el punto de reunión de los aquelarres la noche de Todos los Santos【turn14search15】【turn14search16】【turn15search8】. Atractivos: Espai Montseny, ermita de Sant Segimon, macizo del Montseny.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','misterio','Lugares de misterio y leyendas','Sede de los juicios por brujería de la Catalunya central. Su museo narra la persecución, tortura y muerte de las mujeres condenadas por brujería, con un montaje multimedia basado en hechos reales【turn14search17】【turn15search0】【turn15search3】. Atractivos: Centre d''Interpretació de la Bruixeria.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43169','misterio','Lugares de misterio y leyendas','La Mussara, pedanía despoblada en los años 60, lleva más de 100 años con un misterio sin resolver. Se reportan fenómenos paranormales, apariciones y ruidos inexplicables entre sus ruinas; se ha comparado con el pueblo de "Stranger Things"【turn1search12】【turn1search13】. Atractivos: Pueblo fantasma de La Mussara, Sierra de Prades.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10060','misterio','Lugares de misterio y leyendas','La tradición oral mantiene viva la existencia de brujas en los Ibores, con testimonios recogidos por la Inquisición en la comarca. Es uno de los puntos de brujería documentada de Extremadura【turn9search2】【turn8search0】. Atractivos: Cueva de Castañar (Monumento Natural), Sierra de Villuercas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10102','misterio','Lugares de misterio y leyendas','La Cueva de las Brujas de Ibahernando es un lugar donde "la imaginación se despierta sola", según los lugareños, asociado a leyendas de aquelarres y rituales【turn9search0】. Atractivos: Cueva de las Brujas, casco rural.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','misterio','Lugares de misterio y leyendas','El ex-convento de San Francisco en ruinas es uno de los lugares más inquietantes de Extremadura, frecuentado por amantes del turismo oscuro【turn2search8】. Atractivos: Ex-Convento abandonado de San Francisco, catedral.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12141','misterio','Lugares de misterio y leyendas','Uno de los centros de peregrinación más misteriosos de España. Hasta el siglo XX acudían "endemoniados" para ser exorcizados en el santuario, con testimonios documentados de posesiones y rituales de liberación【turn6search0】【turn6search1】【turn6search4】. Atractivos: Santuario de la Virgen de la Balma (excavado en la roca).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','misterio','Lugares de misterio y leyendas','La leyenda de la Vera Cruz (lignum crucis que apareció milagrosamente en 1231) y la tradición templaria del lugar generan una oferta de rutas de misterio ("Caravaca Misteriosa") donde se narra la doble vela a Dios y al Diablo de los caballeros caídos【turn17search9】【turn17search12】【turn17search13】. Atractivos: Santuario de la Vera Cruz, castillo templario, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30035','misterio','Lugares de misterio y leyendas','La Isla del Barón, en el Mar Menor, es escenario de la leyenda de una aparición femenina la noche de San Juan. Los pescadores relatan haber visto a una mujer de extraordinaria belleza envuelta en un resplandor【turn5search0】. Atractivos: Mar Menor, Isla del Barón.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31135','misterio','Lugares de misterio y leyendas','Uno de los castillos más espectaculares de España: un rey de Navarra tuvo como mascota a un león y un fantasma se pasearía por él. Leyendas templarias, símbolos extraños y figuras llenas de misterio se dan cita en sus muros【turn2search5】【turn2search6】【turn2search8】. Atractivos: Castillo de Javier (siglo XI), basílica, museo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','misterio','Lugares de misterio y leyendas','Una de las alas del palacio, hoy Parador, encierra la leyenda de un fantasma noble medieval. Se escuchan ruidos, lamentos y melodías de otros tiempos, especialmente en la Galería Dorada. Varios testimonios avalan el paseo del espectro del rey Carlos III【turn13search9】【turn13search11】. Atractivos: Palacio Real de Olite (Parador Príncipe de Viana).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90717','misterio','Lugares de misterio y leyendas','Durante la Guerra Civil fue uno de los mayores campos de prisioneros. Murieron unos 750 presos, 231 de ellos en la fuga de mayo de 1938. El lugar es uno de los escenarios de turismo oscuro y parapsicología más visitados del norte【turn5search7】【turn5search9】. Atractivos: Fuerte de San Cristóbal (monte Ezkaba).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','misterio','Lugares de misterio y leyendas','Lugar de la aparición de la Virgen del Pino (8 de septiembre de 1481), patrona de Gran Canaria. La imagen apareció en lo alto de un pino del que brotaba un manantial de aguas medicinales. Es el principal centro de peregrinación mística de la isla【turn17search4】【turn17search6】【turn16search11】. Atractivos: Basílica del Pino, casco histórico, Plaza del Pino.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07040','misterio','Lugares de misterio y leyendas','Leyendas como el "drac de na Coca" (dragón que acechaba en las acequias de la ciudad) y relatos de brujería en el casco antiguo, heredados del pasado musulmán y medieval【turn5search12】【turn5search14】. Atractivos: Catedral, casco antiguo, barrio de la Calatrava.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','misterio','Lugares de misterio y leyendas','Uno de los lugares con mayor concentración de energía telúrica del Mediterráneo. Considerado el "tercer vértice del triángulo de las Bermudas" en la tradición esotérica. Leyendas de apariciones, sirenas, templarios y avistamientos de naves no identificadas【turn12search16】【turn12search18】. Atractivos: Islote rocoso de casi 400 metros al sudoeste de Ibiza, reservas naturales, miradores.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','misterio','Lugares de misterio y leyendas','La habitación 712 del Parador es uno de los lugares con fenómenos paranormales más documentados de España. Se escuchan ruidos, lamentos y melodías de otros tiempos. La leyenda atribuye la presencia al espíritu de Adalés, hija del vizconde Ramón Folch, encerrada por su padre en la torre tras enamorarse de un príncipe árabe; murió al año de reclusión. El perro del vigilante nocturno se negaba a pasar por la zona durante las obras de adaptación【turn1search0】【turn4search20】【turn10search20】【turn10search22】. Atractivos: Castillo de Cardona (Parador, siglo IX), Colegiata de Sant Vicenç, Torre Minyona.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43155','misterio','Lugares de misterio y leyendas','El Parador de Tortosa, ubicado en un castillo musulmán del siglo X, figura entre los Paradores con mayor misterio de España. Se reportan fenómenos inexplicables, sombras y presencias en sus estancias y en las galerías subterráneas【turn11search0】【turn11search2】【turn11search6】. Atractivos: Castillo de la Zuda (Parador), catedral, casco histórico, murallas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','misterio','Lugares de misterio y leyendas','El fantasma de doña Blanca de Borbón, esposa de Pedro I el Cruel, presuntamente envenenada entre estos muros en 1361. Huéspedes y empleados reportan sollozos, arrastrar de cadenas y una silueta difuminada recorriendo los pasillos abovedados. La Torre de Doña Blanca lleva su nombre【turn1search5】【turn1search8】【turn1search9】【turn14search7】. Atractivos: Castillo de Sigüenza (Parador, siglo XII), catedral, casco medieval, Casa del Doncel.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13002','misterio','Lugares de misterio y leyendas','Investigado por el programa Cuarto Milenio (Iker Jiménez y Carmen Porter). Empleadas y huéspedes reportan presencias, sillas que se giran solas y ruidos inexplicables. La habitación 39 es la más activa; varios huéspedes han abandonado el Parador tras vivencias paranormales【turn15search0】【turn15search2】【turn7search16】. Atractivos: Parador de Santa Catalina (antiguo convento), Plaza Mayor, corrales de comedias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','misterio','Lugares de misterio y leyendas','La Catedral de León tiene documentados al menos cuatro fantasmas de personajes ilustres. El Parador de San Marcos, antiguo convento-hospital de peregrinos, cárcel (donde estuvo preso Quevedo) y prisión durante la Guerra Civil, es conocido por la aparición del "fantasma de Quevedo" y otras presencias en sus muros renacentistas【turn9search16】【turn15search5】【turn15search6】【turn17search0】【turn17search1】. Atractivos: Catedral, Hostal de San Marcos (Parador), Casa Botines de Gaudí, Barrio Húmedo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37003','misterio','Lugares de misterio y leyendas','Según la leyenda local, el espíritu de un noble traicionado y asesinado vaga por las murallas en noches de tormenta, vestido con armadura. Los visitantes reportan susurros y pasos en los pasillos vacíos del castillo【turn7search14】【turn7search17】. Atractivos: Castillo de Enrique II de Trastámara (Parador), catedral, murallas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','misterio','Lugares de misterio y leyendas','La leyenda del "noble sin cabeza": Fernán Íñiguez de Coca, condenado por traición, vaga por sus pasillos de ladrillo. Se reportan fantasmas y secretos ocultos en sus gruesos muros【turn2search11】【turn2search12】【turn2search13】. Atractivos: Castillo de Coca (siglo XV, gótico-mudéjar), propiedad de la Casa de Alba.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','misterio','Lugares de misterio y leyendas','Se dice que algunas noches se ven dos figuras espectrales vagando entre las murallas. La leyenda de Elvira y Roberto, amantes cuya historia terminó en tragedia, es la aparición más reportada; en noches de verano se ven sus sombras bajo una "aureola de fuego"【turn1search10】【turn1search12】【turn1search13】. Atractivos: Castillo de Pedraza (siglo XIII), casco medieval, museo de Zuloaga.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34056','misterio','Lugares de misterio y leyendas','Aunque el Parador moderno carece de la carga histórica de otros, la comarca montañesa palentina está llena de leyendas de ojáncanos y tradiciones celtas, y la zona es destino de retiros espirituales【turn16search3】【turn16search4】. Atractivos: Parador de Cervera de Pisuerga, Reserva Natural de Fuentes Carrionas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','misterio','Lugares de misterio y leyendas','El Castillo de Santiago ha sido investigado por equipos de parapsicología que han documentado fenómenos paranormales (psicofonías, imágenes y testimonios). Se realizan visitas especiales "Fenomenología paranormal en el Castillo de Santiago" donde se proyectan los audios e imágenes captados【turn3search0】【turn5search4】【turn5search6】【turn5search7】. Atractivos: Castillo de Santiago (siglo XV), palacios, entrada al Parque de Doñana.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','misterio','Lugares de misterio y leyendas','Free tour específico de "Leyendas y Misterios de Ronda" que recorre la Casa Encantada Rúa (espíritu de una niña asesinada que busca venganza), la calle de la Bola, la Casa del 98, la Capilla de los Ajusticiados y la Sauceda【turn6search8】【turn6search10】【turn6search11】【turn7search3】【turn11search9】【turn11search10】【turn11search11】【turn11search12】【turn11search13】. Atractivos: Casa Rúa (Villa Apolo), calle de la Bola, Casa del 98, Capilla de los Ajusticiados, Puente Árabe, La Sauceda, Plaza de la Merced.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','misterio','Lugares de misterio y leyendas','Apariciones, ritos prohibidos, crímenes y romances en leyendas no contadas. El Torcal de Antequera tiene un halo de misterio ancestral. La Peña de los Enamorados guarda la leyenda de Tagzona y Tello (los amantes que se lanzaron al vacío). El Dolmen de Menga, 1.000 años más antiguo que Stonehenge, orienta su eje hacia la Peña, enigma arqueológico sin resolver【turn5search17】【turn5search20】【turn5search21】【turn11search4】【turn11search5】【turn12search7】【turn12search8】【turn13search10】【turn13search11】【turn13search12】【turn13search13】【turn13search14】. Atractivos: Dólmenes de Menga y Viera, El Torcal, Peña de los Enamorados, Colegiata de Santa María, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','misterio','Lugares de misterio y leyendas','Analizada en el podcast "El Archivo del Misterio" por sus extrañas psicofonías. La Necrópolis romana, con tumbas tan impresionantes como la Tumba del Elefante y la de Servilia, es un foco de actividad paranormal documentada. En 2019 apareció un mausoleo romano en el patio de una vivienda particular【turn0search2】【turn5search12】【turn5search14】【turn5search16】. Atractivos: Necrópolis romana, Anfiteatro, Alcázar de la Puerta de Sevilla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','misterio','Lugares de misterio y leyendas','El primer "ghost tour" sobre Cádiz paranormal recoge apariciones en la calle Mesón y el terrible suceso de 1755. Existe el enigma de la "niña" y la investigación de la calle Valcárcel, donde se sucedieron hechos luctuosos que propiciaron fenómenos insólitos【turn3search1】【turn3search3】【turn3search4】. Atractivos: Castillo de Santa Catalina, casco histórico, calle Mesón.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','misterio','Lugares de misterio y leyendas','Visitado por Iker Jiménez en busca de sucesos paranormales. Los vecinos mayores recuerdan la aparición de un fantasma en los tejados del castillo zafrense en varias ocasiones a lo largo de los años【turn13search17】【turn13search18】. Atractivos: Castillo-Palacio de los Duques de Feria (Parador, siglo XII), casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46109','misterio','Lugares de misterio y leyendas','Uno de los lugares embrujados más famosos de la Comunidad Valenciana. Se han grabado múltiples psicofonías; los investigadores reportan lamentos de niños, rituales, pentagramas y un estruendo impresionante captado al poner un micrófono en el suelo. Investigado por Más Vale Sábado 【turn6search12】【turn6search13】【turn6search14】【turn6search15】. Atractivos: Psiquiátrico abandonado "La Humanitat" (construido 1960-1980, cerrado en 2000).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','misterio','Lugares de misterio y leyendas','Considerada "la isla más paranormal de España". Lugar de aislamiento que acumula psicofonías aterradoras, sombras que se mueven entre las ruinas y el espectro de una misteriosa anciana con bata blanca. Numerosos investigadores han documentado actividad【turn4search0】【turn4search1】【turn4search3】【turn4search4】. Atractivos: Antiguo sanatorio infantil de tuberculosis (isla en la bahía de Santander).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','misterio','Lugares de misterio y leyendas','Tres presencias documentadas: Margarita de Eguilior (de 29 años, que toca el piano y pasea por las escaleras), su hija, y Antonio (antiguo sirviente). Predilección por la habitación 205. Se han obtenido fotografías con el rostro del Conde de Albox y de "Rosita" sosteniendo un bebé【turn12search1】【turn12search2】【turn12search3】【turn11search15】. Atractivos: Parador de Limpias (palacete modernista de principios del siglo XX), Castañar.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','misterio','Lugares de misterio y leyendas','El Castillo de San Telmo es uno de los relatos de fantasmas más conocidos de Gipuzkoa. El Parador acumula testimonios de presencias en sus muros con heridas de bala de cañón【turn12search11】【turn12search12】【turn12search13】【turn18search5】. Atractivos: Parador de Hondarribia (Castillo de Carlos V, s. X), Plaza de Armas, Castillo de San Telmo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90689','misterio','Lugares de misterio y leyendas','Leyenda de la princesa mora cautiva que esperó en vano a su caballero y murió prisionera. Su espíritu vaga por los pasillos. El castillo tiene vínculos esotéricos documentados【turn10search5】【turn10search8】【turn10search9】. Atractivos: Castillo de Butrón (siglo XIII, estética de cuento de hadas).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48041','misterio','Lugares de misterio y leyendas','Ligado a Eugenia de Montijo (emperatriz de Francia). Existe una "leyenda negra" que envuelve al castillo, frecuentado por amantes de lo esotérico【turn10search0】【turn10search2】【turn10search3】. Atractivos: Castillo de Arteaga (siglo XIII, neogótico), Reserva de la Biosfera de Urdaibai.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','misterio','Lugares de misterio y leyendas','El monasterio alberga restos arqueológicos de la estructura original y siglos de historia benedictina. Es uno de los Paradores con más testimonios de presencias【turn16search1】【turn16search2】【turn17search4】【turn17search5】. Atractivos: Parador de Corias (Monasterio de San Juan Bautista, siglo XI, "El Escorial de Asturias"), biblioteca monumental.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','misterio','Lugares de misterio y leyendas','Leyenda de Don Pelayo, que murió enfrentándose a un oso en estos bosques. Los huéspedes reportan hojas que se mueven "por un viento que no existe" y la leyenda del oso【turn12search4】【turn12search5】【turn12search6】. Atractivos: Parador de Cangas de Onís (monasterio de San Pedro de Villanueva, siglo VIII), puentes, Covadonga.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','misterio','Lugares de misterio y leyendas','La Torre del Príncipe inspiró a Alejandro Dumas para El hombre de la máscara de hierro . Leyendas de amantes prohibidos encerrados, del príncipe portugués Alfonso Enríquez y del Conde de Gondomar【turn14search4】【turn14search5】【turn14search6】. Atractivos: Parador de Baiona (Castillo de Monterreal, fortaleza de 3 km de perímetro amurallado), Torre del Príncipe.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','misterio','Lugares de misterio y leyendas','El Parador, antiguo hospital de peregrinos, acumula leyendas de peregrinos fallecidos, apariciones marianas y meigas. Conxo, hospital psiquiátrico desde 1885 con más de 1.200 pacientes en condiciones deplorables, icono del turismo oscuro gallego【turn11search10】【turn11search11】【turn11search14】【turn4search5】【turn4search6】【turn4search7】【turn4search9】. Atractivos: Hostal de los Reyes Católicos (Parador, s. XV), Catedral, casco viejo, Hospital Psiquiátrico de Conxo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','misterio','Lugares de misterio y leyendas','El actual propietario asegura que el fantasma de la primera propietaria de la casa ronda las estancias, especialmente en determinadas fechas. La casa tiene capilla privada y mobiliario antiguo intacto【turn8search14】【turn9search0】【turn9search1】【turn9search3】. Atractivos: Casa Bardaxí (Plaza Mayor, siglo XVII), casco histórico ribagorzano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','misterio','Lugares de misterio y leyendas','El milagro del gallo y la gallina: un joven peregrino alemán, Hugonell, fue injustamente ahorcado y, cuando sus padres fueron a buscarlo, este seguía vivo milagrosamente mientras un gallo asado cantaba. Es Bien de Interés Cultural inmaterial y uno de los misterios más famosos del Camino【turn16search7】【turn16search8】【turn16search10】. Atractivos: Catedral,朝圣之路, mesón tradicional.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18151','misterio','Lugares de misterio y leyendas','La tradición oral alpujarreña conserva leyendas de brujería heredadas de la repoblación con gallegos (que trajeron el culto a las meigas), rituales de fertilidad y apariciones en los barrancos【turn2search12】. Atractivos: Barranco del Poqueira, pueblos blancos de la Alpujarra.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18157','misterio','Lugares de misterio y leyendas','La "Vieja del Blanqueo" forma parte de la tradición oral del municipio, vinculada a la antigua fábrica de blanqueo de papel (dirigida por Berta Wilhelmi) y al patrimonio industrial abandonado de la zona. Las ruinas de la fábrica y los paseos de la central eléctrica (incluidos en rutas como "Los Misterios de Pinos Genil" de Secretos de Granada) generan relatos de presencias y ecos del pasado industrial. La documentación escrita sobre la aparición es escasa, por lo que se mantiene como leyenda oral local【turn0search11】【turn4fetch1】【turn8search0】【turn17search2】【turn3search3】. Atractivos: Antigua Fábrica del Blanqueo de papel (s. XIX, hoy Centro CREA), Fábrica de la Luz, Presa de Pinillos, Pantano de Canales, Centro de Interpretación del Tranvía de la Sierra.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90429','misterio','Lugares de misterio y leyendas','Lugar del fusilamiento de Federico García Lorca (agosto 1936). La Fuente Grande, manantial árabe que abastecía la Alhambra, es uno de los últimos reductos musulmanes en capitular (1491). El entorno está cargado de la energía del Barranco de Víznar y de la "no-muerte" de Lorca (leyenda del panadero que lo encontró malherido)【turn5search8】【turn5search10】【turn6search8】【turn6search10】【turn6search11】【turn10search6】【turn10search7】【turn10search8】【turn15search14】【turn15search16】【turn16search5】【turn16search6】【turn19search1】. Atractivos: Fuente Grande o de las Lágrimas (Aynadamar), Parque Federico García Lorca, Sierra de la Alfaguara.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','misterio','Lugares de misterio y leyendas','Más de 6.500 personas enterradas en fosas comunes en el barranco. Las exhumaciones continúan. Es uno de los escenarios de turismo oscuro más simbólicos de España【turn6search8】【turn9search6】【turn9search7】【turn9search8】【turn9search9】【turn9search10】. Atractivos: Palacio del Cuzco (sede de la represión en 1936), Barranco de Víznar (Lugar de Memoria).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','misterio','Lugares de misterio y leyendas','El hombre sin rostro de la Casa Cervantes . Testigos han visto una figura etérea masculina sin rostro que vaga y desaparece. La historia trágica: hace más de 200 años un hombre cayó al pozo del patio, murió ahogado y su rostro quedó tan deformado que lo taparon con una sábana. También se reportan avistamientos OVNI y procesos de la Inquisición【turn11search7】【turn13search3】【turn13search4】【turn13search5】【turn13search6】【turn13search7】【turn16search3】【turn16search4】. Atractivos: Casa de Cervantes (s. XVI), barrio de La Villa, Palacio de Beniel.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','misterio','Lugares de misterio y leyendas','Trompetas del Apocalipsis y caso de ouija con intervención de la Policía Nacional. Dos mujeres y una menor se comunicaron con el espíritu de un niño llamado Agustín (patrón de la ciudad); cuadros y radiadores se movían solos. La situación fue tan alarmante que requirió la intervención policial【turn17search13】【turn18search1】【turn18search2】【turn18search3】【turn18search4】. Atractivos: Casco histórico minero, Castillo de Tobaruela, plaza de Toros.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','misterio','Lugares de misterio y leyendas','Maldición del callejón de las Brujas . María Santiago Rabadán, juzgada por hechicería en un Auto de Fe en 1655. Investigado por Manuel Jesús Segado Uceda【turn9search11】【turn9search13】【turn10search11】【turn10search12】【turn10search13】. Atractivos: Casco histórico, callejón de las Brujas, restos romanos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','misterio','Lugares de misterio y leyendas','Leyenda del Señor de las Cadenas , la Dama de la Capa y el origen de la expresión "irse por los cerros de Úbeda". La Puerta de Granada oculta un tesoro medieval junto a la muralla árabe. La Casa de los Salvajes acumula relatos inquietantes【turn11search14】【turn11search16】【turn11search18】【turn17search11】【turn17search12】. Atractivos: Casco renacentista (Patrimonio UNESCO), Capilla del Salvador, Casa de los Salvajes, Plazuela, Sinagoga del Agua, Puerta de Granada.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','misterio','Lugares de misterio y leyendas','Pueblos del norte de Jaén unidos por una historia de magia y misterio, exvotos íberos y poemas de Jorge Manrique【turn9search15】. Atractivos: Cueva de la Lobera, santuario ibérico de los Altos del Sotillo, puente romano sobre el Guadalimar.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10049','misterio','Lugares de misterio y leyendas','La Dama Blanca que aparece sentada en noches de tormenta en la carretera Casar de Cáceres-Arroyo de la Luz. Es una de las apariciones en cunetas extremeñas más conocidas【turn0search5】. Atractivos: Carreteras comarcales de Extremadura.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','misterio','Lugares de misterio y leyendas','El hombre alto vestido de negro que continúa suicidándose en la curva de Mirabel. Una de las apariciones de carretera más escalofriantes de Extremadura【turn0search5】. Atractivos: Carretera de la curva de Mirabel.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','misterio','Lugares de misterio y leyendas','La dama de rojo de Miajadas , aparición en cuneta【turn0search5】. Atractivos: Cruce de carreteras en la Serena.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10140','misterio','Lugares de misterio y leyendas','La niña vestida de comunión que se acerca a los coches en la carretera de Peraleda de la Mata【turn0search5】. Atractivos: Carretera local junto al embalse de Orellana.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10127','misterio','Lugares de misterio y leyendas','La joven de la recta de la carretera Montehermoso-Pozuelo de Zarzón【turn0search5】. Atractivos: Carretera de la Sierra de Gata.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42174','misterio','Lugares de misterio y leyendas','El misterio del reloj maldito y el pueblo poseído por el diablo. Un extraño suceso con el reloj del pueblo desencadenó una serie de muertes misteriosas. Inspiró el libro "La rebelión de Lucifer" de J.J. Benítez. Recogido por el programa Palacios y Castillos con Misterio de CyLTV【turn13search11】【turn14search0】【turn14search1】. Atractivos: Iglesia, torre del reloj del pueblo, Sierra de Albarracín.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02047','misterio','Lugares de misterio y leyendas','El fantasma de Masegoso . El pueblo, rico y floreciente, desapareció tras el odio irreconciliable entre dos poderosas familias (Julián Alvarez y Andrés Orozco). Leyenda de desaparición misteriosa de un pueblo entero【turn13search13】. Atractivos: Torre de Masegoso, paisaje serrano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','misterio','Lugares de misterio y leyendas','La antigua Bletisa romana acumula leyendas medievales entre sus calles y murallas, en una de las zonas más mágicas de la provincia【turn3search8】【turn3search9】. Atractivos: Conjunto Histórico-Artístico, castillo, ribera del Tormes, Arribes.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','misterio','Lugares de misterio y leyendas','Pueblo de montaña con tradiciones y leyendas ancestrales, en una de las sierras más mágicas de Salamanca【turn3search9】. Atractivos: Sierra de Candelario, arquitectura tradicional.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','misterio','Lugares de misterio y leyendas','Pueblo mágico por excelencia de Las Batuecas, con tradiciones seculares, leyendas de brujería serrana y ermitas rupestres en el valle. Atractivos: Primer pueblo declarado Conjunto Histórico-Artístico de España, plaza mayor, iglesia.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49166','misterio','Lugares de misterio y leyendas','Cabecera de la comarca de Sanabria, tierra de meigas, conjuros, mal de ojo y el "llobu". Cerca del Lago de Sanabria con su leyenda de Valverde de Lucerna (pueblo sumergido cuyas campanas suenan la noche de San Juan)【turn13search7】【turn13search10】. Atractivos: Villa medieval amurallada, castillo de los Condes de Benavente, río Tera.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','misterio','Lugares de misterio y leyendas','Cuenta con ruta nocturna oficial "Mitos y Leyendas" organizada por el Ayuntamiento, que recorre los secretos que esconde la villa cuando cae la noche【turn0search19】. Atractivos: Villa medieval, Arribes del Duero, bodegas subterráneas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49219','misterio','Lugares de misterio y leyendas','El misterio de la Calle Balborraz : un capitán musulmán que quería destruir la ciudad, una ejecución y una historia de amor. Se cruza con la leyenda de la "Cabeza de Piedra" de la Catedral【turn0search18】. Atractivos: Colegiata, cimborrio, casco histórico, ribera del Duero.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49275','misterio','Lugares de misterio y leyendas','Acoge las Jornadas de Misterio y acumula leyendas como la más oscura de la provincia. La Catedral y la iglesia de San Pedro y San Ildefonso concentran relatos de apariciones【turn2search5】【turn2search6】. Atractivos: Catedral, conjunto románico, puente sobre el Duero, iglesias.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','misterio','Lugares de misterio y leyendas','El misterio del fauno burgalés : en el Jardín Secreto se esconde la escultura de un fauno petrificado por una maldición, guardian de los seres mágicos del bosque. Entrada libre【turn13search15】【turn13search16】. Atractivos: Monasterio de San Salvador, Jardín Secreto, Casa del Parque Montes Obarenes.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','misterio','Lugares de misterio y leyendas','Una de las ciudades más pequeñas de España, con un castillo que acumula leyendas desde el siglo X【turn13search17】【turn13search18】【turn13search19】. Atractivos: Ciudad colgante sobre La Muela, castillo del siglo X, iglesia fortificada de San Vicente.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','misterio','Lugares de misterio y leyendas','Una de las Raíces de Castilla, con un patrimonio cargado de historia y leyendas en el norte de Burgos【turn13search17】【turn13search18】. Atractivos: Salinas romanas, pueblo natal de Félix Rodríguez de la Fuente.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','misterio','Lugares de misterio y leyendas','Villa ducal con un pasado cargado de intrigas palaciegas y leyendas entre sus conventos【turn0search20】【turn1search20】. Atractivos: Ducado de Lerma, conventos, plaza mayor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','misterio','Lugares de misterio y leyendas','Una de las Raíces de Castilla, con un casco histórico que guarda leyendas desde los orígenes del condado【turn0search20】【turn1search20】. Atractivos: Colegiata, casco medieval, origen de Castilla.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47085','misterio','Lugares de misterio y leyendas','La Dama de la Mota y la maldición del castillo. La reina Isabel lo utilizó como residencia y prisión política; varios personajes fueron ejecutados por mandato real entre sus muros. Es uno de los castillos más temidos de Castilla【turn0search10】【turn0search11】【turn0search12】【turn0search14】. Atractivos: Castillo de la Mota (siglo XIII), casco histórico, Plaza Mayor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90805','misterio','Lugares de misterio y leyendas','Uno de los municipios palentinos que más misterios alberga: se habla de energías milenarias , una sociedad intraterrestre y avistamiento de objetos luminosos no identificados en el cielo. Considerado "lugar de poder"【turn0search21】. Atractivos: Casco urbano, entorno natural.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34199','misterio','Lugares de misterio y leyendas','La leyenda dice que Plinio el Viejo mencionó estas fuentes. La zona está cargada de historia y tradiciones ancestrales【turn0search20】. Atractivos: Fuentes romanas de La Reana (más de 2000 años), embalse de Camporredondo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','misterio','Lugares de misterio y leyendas','Ruta "Palencia Misteriosa" de Rutas Misteriosas: episodios paranormales en la Catedral, la Diputación y el antiguo orfanato de Huérfanos Ferroviarios. Viejas leyendas de crímenes sin resolver, desapariciones y el Cristo que desvía los rayos en las tormentas【turn10search14】【turn10search16】【turn10search17】. Atractivos: Catedral de San Antolín ("La Bella Desconocida"), Cristo del Buen Suceso, calle Mayor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','misterio','Lugares de misterio y leyendas','Peñasco estratégico con un casco histórico cargado de leyendas medievales, en uno de los pueblos más singulares de la provincia de Cuenca【turn14search3】【turn14search4】【turn14search5】. Atractivos: Villa medieval amurallada sobre un meandro del Júcar, castillo, iglesia fortificada.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','misterio','Lugares de misterio y leyendas','Antigua ciudad romana y medieval, con un patrimonio cargado de leyendas y tradiciones【turn14search3】. Atractivos: Conjunto histórico, cuatro museos (Arte Sacro, Fragua, Etnográfico, Florencio de la Fuente).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','misterio','Lugares de misterio y leyendas','Uno de los pueblos más bonitos de la provincia, en un paraje natural escénico que acumula tradiciones y leyendas【turn14search3】【turn14search4】. Atractivos: Estrecho de Priego (hoz del río Escabas), casco histórico de la Alcarria conquense.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','misterio','Lugares de misterio y leyendas','En el corazón de la Alcarria, Pastrana ofrece "historia, conventos y leyendas" del Siglo de Oro, con la figura maldita de la princesa de Éboli【turn1search8】. Atractivos: Palacio de la princesa de Éboli, conventos de Carmelitas, plaza Mayor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','misterio','Lugares de misterio y leyendas','Villa medieval con un patrimonio cargado de leyendas de caballeros y tradiciones ancestrales【turn1search9】. Atractivos: Castillo, casco medieval, Caballeros de Atienza.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','misterio','Lugares de misterio y leyendas','Enclave brujeril documentado. Las brujas de Molina se trasladaban hipotéticamente hasta Gallocanta (Zaragoza) para un aquelarre. Una tal Águeda, del siglo XVI, declaró que su abuela había sido bruja y se reunía en Gallocanta【turn9search20】【turn10search1】. Atractivos: Castillo, Señorío de Molina, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','misterio','Lugares de misterio y leyendas','Objeto del libro "Alcarria bruja. Historia de la hechicería en Guadalajara y los procesos de la villa de Pareja", de Javier Fernández Ortea. Procesos de brujería documentados【turn9search23】. Atractivos: Casco urbano de la Alcarria, embalse de Entrepeñas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45165','misterio','Lugares de misterio y leyendas','Acumula leyendas y tradiciones populares de la provincia de Toledo, con un sustrato de misterios recogidos por José Talavera【turn1search10】【turn1search12】【turn1search13】. Atractivos: Casco histórico, cerámica, río Tajo, murallas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','misterio','Lugares de misterio y leyendas','Villa medieval con un castillo que acumula leyendas de nobles y tradiciones, en una de las zonas más mágicas de la provincia de Toledo. Atractivos: Castillo-palacio de los Condes de Oropesa, parador, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45200','misterio','Lugares de misterio y leyendas','Zona conocida por las leyendas de los monjes sobrenaturales , recogidas en el libro de mitos y leyendas de Castilla-La Mancha【turn0search18】. Atractivos: Puerto de los Yébenos, Montes de Toledo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90825','misterio','Lugares de misterio y leyendas','Las minas de Almadén son escenario de la leyenda del Morgo , duende minero que extrae minerales bajo tierra. Tradiciones de brujería y apariciones en una de las comarcas más enigmáticas de CLM【turn0search18】. Atractivos: Minas de mercurio (Patrimonio UNESCO), hospital de mineros, plaza de toros.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13013','misterio','Lugares de misterio y leyendas','Cuenta con leyendas de fantasmas locales, recogidas en rutas y tradiciones orales【turn0search15】. Atractivos: Casco histórico, museos mineros.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13018','misterio','Lugares de misterio y leyendas','La mano negra , el morgo y los fantasmas de Valdepeñas son algunos de sus mitos y leyendas más conocidos【turn0search17】【turn0search18】. Atractivos: Bodegas, plaza Mayor, museo del vino.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','misterio','Lugares de misterio y leyendas','Uno de los pueblos con castillo más impresionantes de Albacete, con historia y leyendas de la Sierra del Segura【turn0search11】【turn0search12】. Atractivos: Castillo de Yeste, Sierra del Segura, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02005','misterio','Lugares de misterio y leyendas','Una de las fortalezas más impresionantes de Albacete, con historia y leyendas asociadas a la famosa batalla【turn0search16】【turn0search2】. Atractivos: Castillo de Almansa (siglo XIV), casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','misterio','Lugares de misterio y leyendas','Uno de los pueblos más bonitos de Albacete, con historia medieval y leyendas【turn3search7】. Atractivos: Plaza Mayor, torres del Salvador y de la Alcadima, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50117','misterio','Lugares de misterio y leyendas','Centro de aquelarres de toda Aragón. Las brujas de la zona se reunían en la laguna, con leyendas de hechicería que recorren la zona desde hace siglos. Las brujas de Molina de Aragón se desplazaban hasta aquí【turn10search0】【turn10search1】. Atractivos: Laguna de Gallocanta (mayor laguna salada de Europa), observatorio de grullas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44158','misterio','Lugares de misterio y leyendas','Comparte nombre con Rubielos de Mora por una leyenda de amor que explica por qué ambos pueblos tienen el mismo nombre invertido【turn1search0】【turn1search2】【turn1search3】. Atractivos: Castillo de Mora, casco histórico, Sierra de Gúdar.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44201','misterio','Lugares de misterio y leyendas','La otra mitad de la leyenda de amor que da nombre a ambos pueblos. calles empedradas y un pasado medieval cargado de historia【turn1search0】【turn1search1】【turn1search2】. Atractivos: Casco histórico medieval, uno de los más bonitos de Teruel.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','misterio','Lugares de misterio y leyendas','Pueblo del Pirineo con chimeneas de brujas y tradiciones mágicas, en un entorno de naturaleza salvaje donde prosperan las leyendas【turn4search12】【turn4search15】. Atractivos: Parque Natural de los Valles Occidentales, arquitectura pirenaica, traje tradicional ansoano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31105','misterio','Lugares de misterio y leyendas','La Cueva de la Mora de Fitero, lugar mágico que cautivó al mismísimo Gustavo Adolfo Bécquer. Es una de las rutas con leyenda más señaladas de Navarra【turn1search11】. Atractivos: Monasterio de Fitero, balnearios, ribera del Alhama.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10082','misterio','Lugares de misterio y leyendas','Uno de los pueblos más misteriosos de Extremadura: duendes, diablos, brujas, monaguillos muertos, pasadizos secretos, sirenas malditas, princesas encantadas, tesoros ocultos y caníbales . La Sirena de Garrovillas y las brujas (entre ellas La Macharra) que salen los sábados por las chimeneas montadas en escobas. La "Ventana del Diablo" de la iglesia de San Pedro【turn11search6】【turn12search1】【turn12search3】【turn13search0】【turn13search1】. Atractivos: Plaza medieval porticada, iglesia de San Pedro (Ventana del Diablo), puente romano de Alconétar.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','misterio','Lugares de misterio y leyendas','Villa monumental con un casco histórico que acumula leyendas desde la Reconquista, en una de las zonas más mágicas de Extremadura【turn11search6】. Atractivos: Plaza Mayor, castillo, casco histórico, cuna de Pizarro.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10148','misterio','Lugares de misterio y leyendas','Ciudad medieval con un casco histórico cargado de leyendas y tradiciones【turn11search6】. Atractivos: Catedral (dos catedrales en una), murallas, palacios.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90838','misterio','Lugares de misterio y leyendas','Aquelarre anual teatralizado basado en los archivos inquisitoriales. Las brujas La Corbacha y La Candelera , famosas en los autos de fe de la Inquisición【turn10search3】. Atractivos: Casco histórico, sierra, tradiciones inquisitoriales.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','misterio','Lugares de misterio y leyendas','Una de las ciudades templarias del sur de Badajoz, con tradiciones y leyendas medievales【turn1search22】. Atractivos: Ciudad templaria, iglesias, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06010','misterio','Lugares de misterio y leyendas','Ciudad templaria con un castillo del siglo XVI y tradiciones de misterio, además de un enclave de astroturismo【turn1search20】【turn1search22】【turn1search23】. Atractivos: Castillo, astroturismo (Entre Encinas y Estrellas), casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','misterio','Lugares de misterio y leyendas','Pueblo señorial con un pasado ligado a la Inquisición, que acumula tradiciones y leyendas【turn1search20】【turn1search22】. Atractivos: Casco histórico, tribunal de la Inquisición, plaza Mayor.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14049','misterio','Lugares de misterio y leyendas','La dama fantasmal de Santa Clara . Los vecinos hablan de una figura blanca femenina que se pasea entre lamentos en el convento. El origen sería un macabro suceso de finales del siglo XV, recogido por el cronista fray Andrés de Guadalupe【turn5search10】【turn6search0】【turn6search1】【turn6search4】. Atractivos: Convento de Santa Clara (hoy hospedería), palacio de Portocarrero, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14075','misterio','Lugares de misterio y leyendas','Uno de los pueblos blancos más bonitos de Córdoba, con un castillo colgado sobre la sierra que acumula leyendas【turn5search14】【turn14search11】. Atractivos: Castillo, cueva de los Murciélagos, pueblo blanco de la Subbética.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','misterio','Lugares de misterio y leyendas','Hogar de relatos misteriosos y tradiciones que han capturado la imaginación de sus habitantes【turn5search14】. Atractivos: Barrio de la Villa, Fuente del Rey, casco histórico barroco.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','misterio','Lugares de misterio y leyendas','Uno de los municipios sevillanos con más historia y tradiciones, recogidas por National Geographic【turn5search16】. Atractivos: Universidad, colegiata, ducado, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','misterio','Lugares de misterio y leyendas','Municipio sevillano con tradiciones únicas y un "estilo ecijano" cargado de leyendas【turn5search16】. Atractivos: Ciudad del barroco, torres, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','misterio','Lugares de misterio y leyendas','Municipio sevillano con imaginería antigua y tradiciones únicas que acumulan leyendas【turn5search16】. Atractivos: Casco histórico, castillo, tradiciones.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41036','misterio','Lugares de misterio y leyendas','La estación encantada de El Coronil , epicentro de fenómenos paranormales en la campiña sevillana. Voces extrañas, sombras que cruzan de una habitación a otra y esferas luminosas en medio de la noche. Recogido por ABC Sevilla【turn6search10】【turn6search11】【turn6search12】【turn6search13】. Atractivos: Antigua estación de tren abandonada, casco urbano.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','misterio','Lugares de misterio y leyendas','El Cortijo de las Ánimas , pueblo fantasma engullido por la presa del pantano del Tranco. La leyenda cuenta que José Requena Carmona tuvo un encuentro con el mismísimo Satanás 【turn6search6】. Atractivos: Parque Natural de Cazorla, Segura y Las Villas, castillo, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','misterio','Lugares de misterio y leyendas','Ciudad con un barrio troglodita y un pasado árabe que acumula leyendas de brujería y apariciones【turn12search5】【turn12search6】. Atractivos: Barrio de las cuevas, catedral, Alcazaba.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','misterio','Lugares de misterio y leyendas','Enclave con poderes curativos desde época romana y árabe, en un paraje de tajos impresionantes que acumulan tradiciones y leyendas【turn12search6】【turn12search8】. Atractivos: Tajos, baños árabes, parque natural de Tejeda, Almijara y Alhama.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','misterio','Lugares de misterio y leyendas','Uno de los pueblos más bonitos de Granada, con un pasado nazarí cargado de leyendas【turn12search5】【turn12search9】. Atractivos: Peña de los Gitanos, iglesia circular, Sierra de Parapanda.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','misterio','Lugares de misterio y leyendas','"Pura historia de Cádiz", fundado por fenicios. Acumula leyendas de brujería y apariciones arraigadas en la cultura popular de la región【turn5search0】【turn5search1】【turn5search2】【turn7search15】. Atractivos: Casco histórico fenicio-romano-árabe, castillo, ducado.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','misterio','Lugares de misterio y leyendas','Municipio cargado de leyendas, con cuaderno de campo "Historias y Leyendas" editado por su turismo【turn5search1】【turn14search7】【turn14search8】. Atractivos: Pueblo blanco amurallado, vistas al Atlántico, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','misterio','Lugares de misterio y leyendas','Historia heroica de Tarifa y leyendas medievales, con un pasado estratégico cargado de tradiciones【turn5search1】. Atractivos: Casco histórico, castillo de Guzmán el Bueno, playas, puntal más al sur de Europa.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','misterio','Lugares de misterio y leyendas','Historia milenaria desde la prehistoria, con huella de fenicios, íberos, cartagineses, romanos y árabes que dejaron vestigios y leyendas【turn5search22】. Atractivos: Casco histórico, Parque Natural de Cabo de Gata-Níjar, playas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90859','misterio','Lugares de misterio y leyendas','La Dama Rosa , fantasma de una mujer que murió dando a luz a su hijo en el sanatorio. Sus llantos se escuchan entre las instalaciones abandonadas, que atendieron a casi 3.000 personas【turn7search0】【turn8search0】【turn8search1】【turn8search2】. Atractivos: Sanatorio San Francisco de Borja de Fontilles (1909), pueblo-sanatorio para enfermos de lepra.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','misterio','Lugares de misterio y leyendas','El "crimen de les Mananes" (1915), tema tabú en Alcoy. Tres curanderas/hechiceras/brujas (dos hermanas y una cuñada) con supuestos poderes sobrenaturales se relacionaron con la desaparición y hallazgo del cuerpo de un niño en una acequia【turn7search2】【turn8search5】【turn8search6】【turn8search7】【turn8search8】. Atractivos: Casco histórico, parques naturales, industria textil.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','misterio','Lugares de misterio y leyendas','Acumula mitos, leyendas y tradiciones como las Voces del Pasado, en una de las zonas más mágicas de Alicante【turn0search6】. Atractivos: Castillo de Atalaya, Tesoro de Villena, casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45017','misterio','Lugares de misterio y leyendas','Túneles secretos bajo el Castillo de Xàtiva, donde el misterio y la historia se entrelazan. Leyendas de los papas Borgia y curiosidades enigmáticas del Hotel Montsant【turn7search9】【turn7search10】. Atractivos: Castillo, casco histórico, cuna de los papas Borgia, Hotel Montsant.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46182','misterio','Lugares de misterio y leyendas','Leyenda cidiana: el castillo se conquistó de noche con un rebaño de cabras con velas encendidas en los cuernos, que hicieron creer a los musulmanes que un gran ejército les atacaba【turn7search13】. Atractivos: Castillo de Olocau, Sierra Calderona.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','misterio','Lugares de misterio y leyendas','Uno de los pueblos más bonitos de Castellón, con magia de piedra y un pasado medieval cargado de leyendas【turn7search4】【turn7search6】. Atractivos: Casco medieval, museo de arte contemporáneo, castillo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','misterio','Lugares de misterio y leyendas','Considerado el "último pueblo templario de España", con un pasado cargado de misterio y tradiciones medievales【turn7search4】【turn7search8】. Atractivos: Casco medieval templario, restos del castillo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43118','misterio','Lugares de misterio y leyendas','Pueblo con calles dedicadas a las brujas . Leyenda del Dip , criatura misteriosa, y de los perros diabólicos que atacaban a los vecinos. Ruta oficial del Dip【turn9search4】【turn9search5】【turn9search6】【turn9search7】【turn9search8】. Atractivos: Casco antiguo medieval, sierra de Llaberia, calles con nombres de brujas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25059','misterio','Lugares de misterio y leyendas','Leyenda de las siete ermitas (seis más la iglesia) que debían construirse para proteger al pueblo de la peste, tras el encuentro de un pastor con un monje ermitaño【turn9search2】. Atractivos: Iglesia de la Asunción, casco urbano pirenaico, pirineos.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','misterio','Lugares de misterio y leyendas','Uno de los conjuntos medievales mejor conservados de Cataluña, con un barrio judío que acumula leyendas y un pasado cargado de historia【turn9search9】【turn9search11】【turn9search12】【turn9search13】. Atractivos: Puente medieval, judería (micvé), casco histórico.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90889','misterio','Lugares de misterio y leyendas','Villa medieval con un centro histórico que conserva el encanto del pasado, con leyendas y tradiciones【turn9search10】【turn9search11】. Atractivos: Basílica de Santa María, casco medieval, antigua capital del condado.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','misterio','Lugares de misterio y leyendas','"Octava Maravilla del Mundo" y uno de los edificios más enigmáticos de España. Considerado "una puerta al infierno que Felipe II se encargó de sellar" . Curaciones milagrosas, movimientos del Sol, estigmatizaciones y una leyenda local sobre una mina cuyas galerías llegaban al infierno【turn9search14】【turn9search15】【turn9search16】【turn10search4】【turn10search5】. Atractivos: Monasterio de San Lorenzo de El Escorial (Patrimonio UNESCO), biblioteca, panteón de reyes, Casita del Príncipe.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','misterio','Lugares de misterio y leyendas','Pueblo medieval de cuento de la sierra de Madrid, con una muralla almenada y un centro urbano cargado de leyendas【turn12search21】【turn12search22】【turn12search23】. Atractivos: Muralla árabe amurallada, castillo, río Lozoya, casco medieval.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','misterio','Lugares de misterio y leyendas','Uno de los pueblos medievales más bonitos de Madrid, con una plaza mayor única y tradiciones centenarias【turn12search21】【turn12search23】【turn12search24】. Atractivos: Plaza Mayor medieval, convento de Clarisas, castillo.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','misterio','Lugares de misterio y leyendas','Castillo medieval de la sierra de Madrid que acumula leyendas de nobles y tradiciones【turn12search21】. Atractivos: Castillo de los Mendoza (siglo XV), embalse de Santillana, Sierra de Guadarrama.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','misterio','Lugares de misterio y leyendas','Free tour oficial de "Misterios y leyendas de Comillas": milagros, sonidos escalofriantes y extrañas apariciones, historias transmitidas de generación en generación【turn3search18】. Atractivos: Capricho de Gaudí, Palacio de Sobrellano, Universidad Pontificia, casco modernista.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','misterio','Lugares de misterio y leyendas','La leyenda de "La Loba de Ruesga" . María Ruiz fue acusada de brujería y de la desaparición de niños, juzgada y condenada a la hoguera. Se dice que su espíritu sigue vagando por el pueblo y se le atribuyen fenómenos paranormales. Basada en un evento histórico real【turn3search17】. Atractivos: Valle de Ruesga, cuevas, naturaleza.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','misterio','Lugares de misterio y leyendas','Pueblo con historias y leyendas recogidas en rutas oficiales【turn3search20】. Atractivos: Casco histórico, castillo, iglesia, ría, puente.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','misterio','Lugares de misterio y leyendas','La xana de la cascada del Cioyo , una de las historias más tristes de las xanas asturianas【turn3search12】【turn11search18】. Atractivos: Ría del Eo, cascada del Cioyo, acantilados.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','misterio','Lugares de misterio y leyendas','Leyendas del diablo burlón , un personaje benigno que toma presencia humana o animal y disfruta riéndose de la gente. Recopiladas por Aurelio de Llano【turn3search15】. Atractivos: Picos de Europa, Covadonga, Benia de Onís.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','misterio','Lugares de misterio y leyendas','Torre medieval defensiva contra vikingos, en una zona de tradiciones mágicas y meigas【turn2search22】. Atractivos: Torre de San Sadurniño (siglo VIII, defensa contra vikingos), casco histórico, Rías Baixas.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','misterio','Lugares de misterio y leyendas','El Bosque Encantado de Aldán , con restos de un minúsculo castillo inacabado con foso y almenas【turn2search22】. Atractivos: Bosque Encantado de Aldán, castillo inacabado, rías.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','misterio','Lugares de misterio y leyendas','Uno de los pueblos más bonitos de Ourense, con un casco medieval cargado de leyendas【turn2search15】【turn2search16】【turn2search17】. Atractivos: Casco histórico medieval, conjunto histórico-artístico, río Arnoya.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','misterio','Lugares de misterio y leyendas','La capilla mozárabe de San Miguel, joya del año 937, guarda tradiciones y leyendas ancestrales en uno de los conjuntos más místicos de Galicia【turn2search14】【turn2search17】. Atractivos: Monasterio de San Salvador, iglesia de San Rosendo, capilla mozárabe de San Miguel (año 937).','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','misterio','Lugares de misterio y leyendas','Leyenda del puente construido por Santo Telmo (patrón de los marineros), que predicó ante una multitud y dividió las nubes en dos. Judería con tradiciones seculares【turn2search17】【turn2search18】【turn2search20】. Atractivos: Casco medieval, judería, castillo, puente sobre el Miño.','inventario_misterioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','misterio','Lugares de misterio y leyendas','Uno de los pueblos más bonitos de Ourense, con un castillo que acumula leyendas sobre el Sil y la Ribeira Sacra【turn2search17】. Atractivos: Castillo, casco histórico, ribeira del Sil.','inventario_misterioso_pdf');
